oxy_webhelp_navlinks = {"mdb_logic_br_plan_protection-d39307e36414":{"topics":[{"title":"<span class=\"ph\">RSC<\/span> user management for MongoDB logical backup and recovery","shortdesc":"<p class=\"shortdesc\">Designating specific users with appropriate privileges and roles in <span class=\"ph\">RSC<\/span> enhances security for protecting your MongoDB logical backup and recovery         sources.<\/p>","href":"mongodb\/mdb_logic_br_user_management.html","attributes":{"data-id":"mdb_logic_br_user_management"},"menu":{"hasChildren":false},"tocID":"mdb_logic_br_user_management-d39307e36428","next":"mdb_logic_br_user_management-d39307e36428"},{"title":"Required <span class=\"ph\">RSC<\/span> permissions for MongoDB logical backup and recovery","shortdesc":"<p class=\"shortdesc\">Information about the permissions that <span class=\"ph\">RSC<\/span> requires in your MongoDB         environment to protect your logical backup and recovery sources.<\/p>","href":"mongodb\/mdb_logic_br_req_rsc_perms.html","attributes":{"data-id":"mdb_logic_br_req_rsc_perms"},"menu":{"hasChildren":false},"tocID":"mdb_logic_br_req_rsc_perms-d39307e36458","next":"mdb_logic_br_req_rsc_perms-d39307e36458"},{"title":"Large-scale sharded MongoDB deployment support","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports data protection for large-scale MongoDB deployments with         sharded clusters of up to 30 shards in Rubrik CDM 9.6.0 and later.<\/p>","href":"mongodb\/mdb_large_scale_sharded_support.html","attributes":{"data-id":"mdb_large_scale_sharded_support"},"menu":{"hasChildren":false},"tocID":"mdb_large_scale_sharded_support-d39307e36486","topics":[]},{"title":"Limitations for MongoDB objects with logical backup and recovery","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> has specific limitations for MongoDB objects with logical backup         and recovery.<\/p>","href":"mongodb\/mongodb_db_limitations.html","attributes":{"data-id":"mongodb_db_limitations"},"menu":{"hasChildren":false},"tocID":"mongodb_db_limitations-d39307e36499","topics":[]},{"title":"MongoDB Admin DB object for RBAC backup and recovery","shortdesc":"<p class=\"shortdesc\">The Admin DB object         protects         the RBAC configuration of a MongoDB source, including custom roles and         users. Recovery applies at the source level, so it affects the users and roles for every         database in the source.<\/p>","href":"mongodb\/mdb_rbac_backup_restore_overview.html","attributes":{"data-id":"mdb_rbac_backup_restore_overview"},"menu":{"hasChildren":false},"tocID":"mdb_rbac_backup_restore_overview-d39307e36512","next":"mdb_rbac_backup_restore_overview-d39307e36512"}]}};